// bidict.mjs
// Minimal re-implementation of the observable behavior of Python's `bidict`,
// using plain JavaScript objects (prototype-free) for dual-direction
// key/value management. No Map, no external dependencies.

/**
 * A bidirectional dictionary: keys map to values and values map back to keys.
 */
export class Bidict {
  constructor(entries) {
    // Prototype-free objects so arbitrary keys like "constructor" or
    // "__proto__" behave like plain data, mirroring Python dict semantics.
    this._forward = Object.create(null); // key   -> value
    this._inverse = Object.create(null); // value -> key
    if (entries != null) {
      const pairs = Array.isArray(entries)
        ? entries
        : Object.entries(entries);
      for (const [k, v] of pairs) {
        this.put(k, v);
      }
    }
  }

  /**
   * Insert or overwrite a key/value pair, keeping both directions consistent
   * (mirrors bidict's on-write duplication handling: the overwritten side is
   * removed from the opposite direction).
   */
  put(key, value) {
    if (Object.prototype.hasOwnProperty.call(this._forward, key)) {
      const oldValue = this._forward[key];
      if (oldValue === value) return;
      delete this._inverse[oldValue];
    }
    if (Object.prototype.hasOwnProperty.call(this._inverse, value)) {
      const oldKey = this._inverse[value];
      delete this._forward[oldKey];
    }
    this._forward[key] = value;
    this._inverse[value] = key;
  }

  /** Membership test on the forward mapping: `key in b`. */
  hasKey(key) {
    return Object.prototype.hasOwnProperty.call(this._forward, key);
  }

  /**
   * The inverse view (`b.inv` in Python). Membership tests on it ask
   * whether a value exists among the original values.
   */
  get inv() {
    const inverse = this._inverse;
    return {
      has: (value) => Object.prototype.hasOwnProperty.call(inverse, value),
    };
  }
}

