// argparser.mjs
// Minimal re-implementation of the observable behavior of Python's argparse
// for the cases used by this program: string and int options, required
// flags, usage/error reporting to stderr, and exit code 2 on failure.

import path from 'node:path';

function progName() {
  // argparse uses os.path.basename(sys.argv[0]); the Node equivalent is the
  // script filename.
  return path.basename(process.argv[1] || 'test6.mjs');
}

export class ArgumentParser {
  constructor() {
    this._options = []; // { name, dest, type, required, metavar }
    this._addHelp();
  }

  _addHelp() {
    this._options.push({
      name: '-h',
      alias: '--help',
      dest: 'help',
      type: 'flag',
      required: false,
      metavar: null,
    });
  }

  /**
   * spec: { name: '--key', type: 'str' | 'int', required: bool }
   */
  addArgument(spec) {
    const dest = spec.name.replace(/^--?/, '').replace(/-/g, '_');
    this._options.push({
      name: spec.name,
      alias: null,
      dest,
      type: spec.type || 'str',
      required: Boolean(spec.required),
      metavar: dest.toUpperCase(),
    });
  }

  _usage() {
    const parts = [];
    for (const opt of this._options) {
      if (opt.type === 'flag') {
        parts.push(`[${opt.name}]`);
      } else if (opt.required) {
        parts.push(`${opt.name} ${opt.metavar}`);
      } else {
        parts.push(`[${opt.name} ${opt.metavar}]`);
      }
    }
    return `usage: ${progName()} ${parts.join(' ')}`;
  }

  _error(message) {
    process.stderr.write(`${this._usage()}\n`);
    process.stderr.write(`${progName()}: error: ${message}\n`);
    process.exit(2);
  }

  _printHelp() {
    process.stdout.write(`${this._usage()}\n`);
    process.exit(0);
  }

  /**
   * Parse argv (default: process.argv.slice(2)) and return a plain object
   * keyed by dest. Mirrors argparse error behavior with exit code 2.
   */
  parseArgs(argv = process.argv.slice(2)) {
    const result = {};
    const byName = new MapObject();
    for (const opt of this._options) {
      byName.set(opt.name, opt);
      if (opt.alias) byName.set(opt.alias, opt);
    }

    const extras = [];
    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];
      const opt = byName.get(token);
      if (opt === undefined) {
        extras.push(token);
        continue;
      }
      if (opt.type === 'flag') {
        if (opt.dest === 'help') this._printHelp();
        result[opt.dest] = true;
        continue;
      }
      if (i + 1 >= argv.length) {
        this._error(`argument ${opt.name}: expected one argument`);
      }
      const raw = argv[++i];
      result[opt.dest] = this._convert(opt, raw);
    }

    const missing = this._options.filter(
      (o) => o.required && !(o.dest in result),
    );
    if (missing.length > 0) {
      const names = missing.map((o) => o.name).join(', ');
      this._error(`the following arguments are required: ${names}`);
    }
    if (extras.length > 0) {
      this._error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return result;
  }

  _convert(opt, raw) {
    if (opt.type === 'int') return parsePythonInt(opt.name, raw, (m) => this._error(m));
    return raw; // 'str'
  }
}

/**
 * Mirror Python's int(str): optional surrounding whitespace, optional sign,
 * then ASCII digits only. Anything else is an invalid int value.
 */
function parsePythonInt(optName, raw, fail) {
  const trimmed = raw.trim();
  if (!/^[+-]?[0-9]+$/.test(trimmed)) {
    fail(`argument ${optName}: invalid int value: '${raw}'`);
  }
  return parseInt(trimmed, 10);
}

// Small helper so this module itself avoids any Map-like interface while
// still supporting prototype-free lookups of option names.
class MapObject {
  constructor() {
    this._store = Object.create(null);
  }
  set(key, value) {
    this._store[key] = value;
  }
  get(key) {
    return Object.prototype.hasOwnProperty.call(this._store, key)
      ? this._store[key]
      : undefined;
  }
}

