// test6.mjs
// Node.js (ESM) port of /workspace/dataset/bidict/test6.py
// Usage: node test6.mjs --key <str> --val <int>

import { ArgumentParser } from './lib/argparser.mjs';
import { Bidict } from './lib/bidict.mjs';

// Python prints booleans capitalized: True / False.
function pyBool(value) {
  return value ? 'True' : 'False';
}

const parser = new ArgumentParser();
parser.addArgument({ name: '--key', type: 'str', required: true });
parser.addArgument({ name: '--val', type: 'int', required: true });
const args = parser.parseArgs();

// 检查键和值的存在性
const b = new Bidict({ a: 1, b: 2, c: 3 });
const result1 = b.hasKey(args.key); // args.key in b
const result2 = b.inv.has(args.val); // args.val in b.inv
console.log(pyBool(result1));
console.log(pyBool(result2));

